('Guerre d Ōnin', 'guerre-onin-japon-JP', '1467-05-01', '1477-01-01', 'La guerre d Ōnin plonge Kyoto dans un conflit qui contribue à l éclatement politique de la période Sengoku.', NULL, 6),
('Bataille de Sekigahara', 'bataille-sekigahara-japon-JP', '1600-10-21', '1600-10-21', 'Tokugawa Ieyasu remporte la bataille de Sekigahara et consolide sa domination politique sur le Japon.', NULL, 7),
('Fondation du shogunat Tokugawa', 'fondation-shogunat-tokugawa-japon-JP', '1603-03-24', '1603-03-24', 'Tokugawa Ieyasu reçoit le titre de shogun et fonde le shogunat Tokugawa.', NULL, 16),
('Politique de fermeture du Japon', 'politique-fermeture-japon-japon-JP', '1639-01-01', '1639-01-01', 'Le shogunat Tokugawa renforce les restrictions sur les contacts et le commerce avec les puissances étrangères.', NULL, 22),
('Restauration de Meiji', 'restauration-meiji-japon-JP', '1868-01-03', '1868-01-03', 'La restauration de Meiji met fin au shogunat Tokugawa et rétablit le pouvoir impérial.', NULL, 8),
('Constitution de Meiji', 'constitution-meiji-japon-JP', '1889-02-11', '1889-02-11', 'La Constitution de l Empire du Japon est promulguée et établit un nouveau cadre politique impérial.', NULL, 22),
('Guerre russo-japonaise', 'guerre-russo-japonaise-japon-JP', '1904-02-08', '1905-09-05', 'Le Japon affronte la Russie dans une guerre pour le contrôle de la Mandchourie et de la Corée.', NULL, 6),
('Capitulation du Japon', 'capitulation-japon-JP', '1945-08-15', '1945-08-15', 'L empereur Hirohito annonce l acceptation des conditions de la capitulation du Japon à la fin de la Seconde Guerre mondiale.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement du royaume nabatéen', 'developpement-royaume-nabateen-jordanie-JO', '0106-01-01', '0168-01-01', 'Le royaume nabatéen se développe autour de Pétra et contrôle d importantes routes commerciales du Proche-Orient.', NULL, 5),
