('Développement ayyoubide en Jordanie', 'developpement-ayyoubide-jordanie-JO', '1187-01-01', '1250-01-01', 'Après les conquêtes de Saladin, la Jordanie s intègre aux territoires ayyoubides.', NULL, 5),
('Développement mamelouk en Jordanie', 'developpement-mamelouk-jordanie-JO', '1250-01-01', '1516-01-01', 'La Jordanie fait partie de l espace mamelouk et bénéficie du développement des routes et des fortifications.', NULL, 5),
('Conquête ottomane de la Jordanie', 'conquete-ottomane-jordanie-JO', '1516-01-01', '1517-01-01', 'Les Ottomans conquièrent la région et l intègrent à leur empire.', NULL, 12),
('Révolte arabe en Jordanie', 'revolte-arabe-jordanie-JO', '1916-06-10', '1918-10-01', 'La révolte arabe contre l Empire ottoman s étend aux territoires de l actuelle Jordanie.', NULL, 9),
('Émirat de Transjordanie', 'fondation-emirat-transjordanie-JO', '1921-03-21', '1921-03-21', 'Abdallah ibn Hussein devient émir de Transjordanie sous mandat britannique.', NULL, 16),
('Indépendance de la Transjordanie', 'independance-transjordanie-JO', '1946-05-25', '1946-05-25', 'La Transjordanie devient officiellement indépendante et le royaume hachémite est proclamé.', NULL, 11),
('Proclamation du Royaume hachémite de Jordanie', 'proclamation-royaume-hachemite-jordanie-JO', '1949-04-01', '1949-04-01', 'L État prend officiellement le nom de Royaume hachémite de Jordanie après l intégration de la Cisjordanie.', NULL, 22),
('Traité de paix jordano-israélien', 'traite-paix-jordano-israelien-jordanie-JO', '1994-10-26', '1994-10-26', 'La Jordanie et Israël signent un traité de paix mettant officiellement fin à leur état de guerre.', NULL, 14);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
