('Développement de la confédération kimek', 'developpement-confederation-kimek-kazakhstan-KZ', '0760-01-01', '1030-01-01', 'La confédération kimek s impose dans les steppes du nord-est du Kazakhstan médiéval.', NULL, 5),
('Développement du khanat kiptchak', 'developpement-khanat-kiptchak-kazakhstan-KZ', '1050-01-01', '1219-01-01', 'Les Kiptchaks dominent une vaste partie des steppes kazakhes et développent de puissants réseaux nomades.', NULL, 5),
('Conquête mongole des steppes kazakhes', 'conquete-mongole-steppes-kazakhes-kazakhstan-KZ', '1219-01-01', '1224-01-01', 'Les armées mongoles conquièrent les territoires du Kazakhstan et les intègrent à l empire mongol.', NULL, 12),
('Fondation de la Horde d Or', 'fondation-horde-or-kazakhstan-KZ', '1242-01-01', '1242-01-01', 'La Horde d Or se constitue dans les territoires occidentaux de l empire mongol et domine une grande partie des steppes.', NULL, 16),
('Formation du khanat kazakh', 'fondation-khanat-kazakh-kazakhstan-KZ', '1465-01-01', '1466-01-01', 'Kereï et Janibek fondent le khanat kazakh, considéré comme l une des bases politiques de l État kazakh.', NULL, 16),
('Développement du khanat kazakh', 'developpement-khanat-kazakh-kazakhstan-KZ', '1465-01-01', '1511-01-01', 'Le khanat kazakh étend son influence sur une grande partie des steppes de l actuel Kazakhstan.', NULL, 5),
('Conquête russe des steppes kazakhes', 'conquete-russe-steppes-kazakhes-kazakhstan-KZ', '1731-01-01', '1868-01-01', 'L Empire russe étend progressivement son contrôle sur les différents territoires du khanat kazakh.', NULL, 12),
('Révolte de Kenesary Khan', 'revolte-kenesary-khan-kazakhstan-KZ', '1837-01-01', '1847-01-01', 'Kenesary Khan dirige une importante résistance contre l expansion de l Empire russe dans les steppes kazakhes.', NULL, 9),
('Création de la République socialiste soviétique kazakhe', 'creation-republique-socialiste-sovietique-kazakhe-kazakhstan-KZ', '1936-12-05', '1936-12-05', 'La République socialiste soviétique kazakhe devient une république constitutive de l Union soviétique.', NULL, 17),
('Déplacement de la capitale à Almaty', 'deplacement-capitale-almaty-kazakhstan-KZ', '1929-01-01', '1929-01-01', 'Almaty devient la capitale de la République socialiste soviétique kazakhe.', NULL, 22),
('Indépendance du Kazakhstan', 'independance-kazakhstan-KZ', '1991-12-16', '1991-12-16', 'Le Kazakhstan proclame son indépendance à la suite de la dissolution de l Union soviétique.', NULL, 11),
('Transfert de la capitale à Astana', 'transfert-capitale-astana-kazakhstan-KZ', '1997-12-10', '1997-12-10', 'La capitale du Kazakhstan est officiellement transférée d Almaty à Akmola, future Astana.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des cultures de l âge du bronze au Kirghizistan', 'developpement-cultures-age-bronze-kirghizistan-KG', '0200-01-01', '0800-01-01', 'Les communautés de l âge du bronze développent l élevage, la métallurgie et les échanges dans les régions montagneuses de l actuel Kirghizistan.', NULL, 24),
('Développement de la culture scythe', 'developpement-culture-scythe-kirghizistan-KG', '0200-01-01', '0700-01-01', 'Les populations nomades de la région développent des traditions scythes et participent aux réseaux des steppes eurasiatiques.', NULL, 24),
('Développement des routes de la soie', 'developpement-routes-soie-kirghizistan-KG', '0100-01-01', '0700-01-01', 'Les vallées du Tian Shan deviennent des voies de passage importantes entre la Chine, l Asie centrale et l Occident.', NULL, 25),
('Développement du khaganat turc', 'developpement-khaganat-turc-kirghizistan-KG', '0552-01-01', '0744-01-01', 'Le khaganat turc étend son influence sur les territoires correspondant en partie au Kirghizistan actuel.', NULL, 5),
('Développement du khaganat turc occidental', 'developpement-khaganat-turc-occidental-kirghizistan-KG', '0603-01-01', '0744-01-01', 'Le khaganat turc occidental contrôle une partie importante des routes commerciales du Tian Shan.', NULL, 5),
('Bataille de Talas', 'bataille-talas-kirghizistan-KG', '0751-07-01', '0751-07-01', 'La bataille de Talas oppose les forces abbassides alliées aux Karlouks à l armée chinoise des Tang.', NULL, 7),
('Développement des Karlouks', 'developpement-karlouks-kirghizistan-KG', '0756-01-01', '0940-01-01', 'Les Karlouks s établissent dans les régions du Tian Shan et jouent un rôle majeur dans les échanges d Asie centrale.', NULL, 5),
('Développement du khanat kimek', 'developpement-khanat-kimek-kirghizistan-KG', '0760-01-01', '1030-01-01', 'Les populations kimek participent à l organisation politique et commerciale des steppes et régions voisines.', NULL, 5),
('Développement du khanat kara-khanide', 'developpement-khanat-kara-khanide-kirghizistan-KG', '0940-01-01', '1212-01-01', 'Les Kara-Khanides établissent un État musulman important en Asie centrale, notamment dans les régions du Tian Shan.', NULL, 5),
('Développement de Balasagun', 'developpement-balasagun-kirghizistan-KG', '0940-01-01', '1218-01-01', 'Balasagun devient un important centre politique, culturel et commercial du khanat kara-khanide.', NULL, 24),
('Diffusion de l islam au Kirghizistan', 'diffusion-islam-kirghizistan-KG', '0960-01-01', '1200-01-01', 'L islam se diffuse progressivement parmi les populations sédentaires et nomades de la région.', NULL, 23),
('Conquête mongole du Kirghizistan', 'conquete-mongole-kirghizistan-KG', '1218-01-01', '1221-01-01', 'Les armées mongoles conquièrent les territoires du Tian Shan et les intègrent à l empire mongol.', NULL, 12),
('Développement du khanat de Djaghataï', 'developpement-khanat-djaghatai-kirghizistan-KG', '1227-01-01', '1370-01-01', 'Le territoire kirghiz fait partie de l espace politique du khanat de Djaghataï.', NULL, 5),
('Développement des Moghols du Chagatai', 'developpement-moghols-chagatai-kirghizistan-KG', '1347-01-01', '1514-01-01', 'Les Moghols du Chagatai dominent une partie du Tian Shan et entretiennent des liens avec les tribus kirghizes.', NULL, 5),
('Développement des tribus kirghizes', 'developpement-tribus-kirghizes-kirghizistan-KG', '1400-01-01', '1600-01-01', 'Les tribus kirghizes renforcent progressivement leur organisation politique et leur présence dans le Tian Shan.', NULL, 5),
('Conquête russe du nord du Kirghizistan', 'conquete-russe-nord-kirghizistan-KG', '1855-01-01', '1868-01-01', 'L Empire russe étend progressivement son contrôle sur les territoires septentrionaux du Kirghizistan.', NULL, 12),
('Révolte de 1916 au Turkestan', 'revolte-1916-turkestan-kirghizistan-KG', '1916-07-01', '1916-12-01', 'Une importante révolte contre l administration russe éclate au Turkestan et touche durement les populations kirghizes.', NULL, 9),
('Création de la République socialiste soviétique kirghize', 'creation-republique-socialiste-sovietique-kirghize-kirghizistan-KG', '1936-12-05', '1936-12-05', 'La République socialiste soviétique kirghize devient une république constitutive de l Union soviétique.', NULL, 17),
('Indépendance du Kirghizistan', 'independance-kirghizistan-KG', '1991-08-31', '1991-08-31', 'Le Kirghizistan proclame son indépendance à la suite de la dissolution progressive de l Union soviétique.', NULL, 11),
('Adoption de la Constitution du Kirghizistan', 'adoption-constitution-kirghizistan-KG', '1993-05-05', '1993-05-05', 'Le Kirghizistan adopte sa première Constitution en tant qu État indépendant.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des établissements de Dilmun', 'developpement-etablissements-dilmun-koweit-KW', '0200-01-01', '0600-01-01', 'La région du Koweït participe aux réseaux commerciaux du golfe Persique liés à la civilisation de Dilmun.', NULL, 25),
('Développement du commerce maritime du golfe Persique', 'developpement-commerce-maritime-golfe-persique-koweit-KW', '0100-01-01', '0700-01-01', 'Les ports et îles de la région participent aux échanges maritimes entre la Mésopotamie, la Perse et l Arabie.', NULL, 25),
('Conquête musulmane de la région du Koweït', 'conquete-musulmane-region-koweit-KW', '0630-01-01', '0638-01-01', 'La région du Koweït est intégrée au territoire des premiers califats musulmans.', NULL, 12),
('Développement abbasside du golfe Persique', 'developpement-abbasside-golfe-persique-koweit-KW', '0750-01-01', '0900-01-01', 'La région du Koweït bénéficie des échanges maritimes associés à l essor du califat abbasside.', NULL, 25),
('Développement du commerce maritime avec l Inde', 'developpement-commerce-inde-koweit-KW', '0800-01-01', '1200-01-01', 'Les marchands de la région développent les échanges avec l Inde et les autres ports de l océan Indien.', NULL, 25),
('Développement des routes commerciales du golfe', 'developpement-routes-commerciales-golfe-koweit-KW', '1000-01-01', '1400-01-01', 'Les routes maritimes du golfe Persique renforcent le rôle commercial de la région du Koweït.', NULL, 25),
('Conquête mongole de l Irak et influence régionale', 'conquete-mongole-irak-influence-koweit-KW', '1258-01-01', '1258-01-01', 'La prise de Bagdad par les Mongols bouleverse les réseaux politiques et commerciaux du golfe Persique.', NULL, 12),
('Développement du commerce sous les Ilkhanides', 'developpement-commerce-ilkhanides-koweit-KW', '1258-01-01', '1335-01-01', 'Les échanges maritimes du golfe Persique se poursuivent sous la domination mongole de l Irak et de la Perse.', NULL, 25),
('Développement du port de Koweït', 'developpement-port-koweit-KW', '1600-01-01', '1700-01-01', 'Le site de Koweït devient progressivement un centre de commerce maritime et de pêche dans le nord du golfe.', NULL, 25),
('Fondation de la ville de Koweït', 'fondation-ville-koweit-KW', '1716-01-01', '1716-01-01', 'La ville de Koweït se développe autour d une communauté de marchands et de pêcheurs issue de la tribu Al-Sabah.', NULL, 16),
('Établissement de la dynastie Al-Sabah', 'etablissement-dynastie-al-sabah-koweit-KW', '1756-01-01', '1756-01-01', 'La famille Al-Sabah prend la direction politique de Koweït et établit une dynastie qui gouverne le territoire.', NULL, 5),
('Développement de la pêche aux perles', 'developpement-peche-perles-koweit-KW', '1750-01-01', '1900-01-01', 'La pêche aux perles devient une activité économique majeure et soutient le commerce maritime de Koweït.', NULL, 25),
('Traité de protection britannique du Koweït', 'traite-protection-britannique-koweit-KW', '1899-01-23', '1899-01-23', 'Le cheikh Mubarak Al-Sabah signe un accord plaçant les relations extérieures du Koweït sous protection britannique.', NULL, 14),
('Découverte du pétrole au Koweït', 'decouverte-petrole-koweit-KW', '1938-02-22', '1938-02-22', 'Du pétrole est découvert à Burgan, marquant le début de la transformation économique du Koweït.', NULL, 18),
('Première exportation de pétrole du Koweït', 'premiere-exportation-petrole-koweit-KW', '1946-06-30', '1946-06-30', 'Le Koweït exporte pour la première fois du pétrole à grande échelle, accélérant son développement économique.', NULL, 25),
('Indépendance du Koweït', 'independance-koweit-KW', '1961-06-19', '1961-06-19', 'Le Koweït devient officiellement indépendant du Royaume-Uni.', NULL, 11),
('Adoption de la Constitution du Koweït', 'adoption-constitution-koweit-KW', '1962-11-11', '1962-11-11', 'Le Koweït adopte une Constitution établissant un système politique fondé sur une monarchie constitutionnelle.', NULL, 22),
('Invasion du Koweït par l Irak', 'invasion-koweit-irak-KW', '1990-08-02', '1990-08-02', 'L Irak envahit le Koweït et occupe le pays, déclenchant une crise internationale majeure.', NULL, 13),
('Libération du Koweït', 'liberation-koweit-KW', '1991-02-26', '1991-02-26', 'Les forces de la coalition libèrent le Koweït après la guerre du Golfe.', NULL, 12),
('Incendies des puits de pétrole koweïtiens', 'incendies-puits-petrole-koweit-KW', '1991-02-16', '1991-11-06', 'Les forces irakiennes en retraite incendient des centaines de puits de pétrole, provoquant une catastrophe environnementale majeure.', NULL, 20);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des premières communautés agricoles du Laos', 'developpement-communautes-agricoles-laos-LA', '0200-01-01', '0500-01-01', 'Les communautés agricoles se développent dans les vallées du Mékong et établissent des réseaux locaux d échanges.', NULL, 24),
