('Développement de Kedah ancien', 'developpement-kedah-ancien-malaisie-MY', '0400-01-01', '0800-01-01', 'Kedah devient un important centre commercial et maritime de la péninsule malaise.', NULL, 25),
('Développement de l influence de Srivijaya', 'developpement-influence-srivijaya-malaisie-MY', '0700-01-01', '1100-01-01', 'Srivijaya exerce une forte influence commerciale et politique sur la péninsule malaise.', NULL, 5),
('Diffusion de l hindouisme et du bouddhisme', 'diffusion-hindouisme-bouddhisme-malaisie-MY', '0500-01-01', '1200-01-01', 'Les traditions hindoues et bouddhistes se diffusent dans les centres commerciaux de la péninsule.', NULL, 23),
('Développement des ports de la péninsule malaise', 'developpement-ports-peninsule-malaise-MY', '0800-01-01', '1300-01-01', 'Les ports de la péninsule renforcent leur rôle dans les échanges maritimes de l Asie du Sud-Est.', NULL, 25),
('Développement de l influence khmère', 'developpement-influence-khmere-malaisie-MY', '0900-01-01', '1200-01-01', 'L influence politique et culturelle khmère atteint certaines régions septentrionales de la péninsule malaise.', NULL, 5),
('Fondation du sultanat de Kedah', 'fondation-sultanat-kedah-malaisie-MY', '1136-01-01', '1136-01-01', 'Le souverain de Kedah adopte l islam et le sultanat de Kedah se consolide comme État musulman.', NULL, 16),
('Développement de l islam dans la péninsule malaise', 'developpement-islam-peninsule-malaise-MY', '1200-01-01', '1500-01-01', 'L islam se diffuse progressivement dans les ports et les principautés de la péninsule malaise.', NULL, 23),
('Fondation du sultanat de Malacca', 'fondation-sultanat-malacca-malaisie-MY', '1400-01-01', '1400-01-01', 'Parameswara fonde le sultanat de Malacca, qui devient rapidement un centre majeur du commerce régional.', NULL, 16),
('Apogée du sultanat de Malacca', 'apogee-sultanat-malacca-malaisie-MY', '1450-01-01', '1500-01-01', 'Malacca devient l un des principaux ports commerciaux de l Asie du Sud-Est et un centre majeur de diffusion de l islam.', NULL, 25),
('Conquête portugaise de Malacca', 'conquete-portugaise-malacca-malaisie-MY', '1511-08-15', '1511-08-15', 'Les Portugais conquièrent Malacca et prennent le contrôle d un important carrefour commercial maritime.', NULL, 12),
('Développement du sultanat de Johor', 'developpement-sultanat-johor-malaisie-MY', '1528-01-01', '1700-01-01', 'Le sultanat de Johor s impose comme une puissance importante après la chute de Malacca.', NULL, 5),
('Conquête néerlandaise de Malacca', 'conquete-neerlandaise-malacca-malaisie-MY', '1641-01-14', '1641-01-14', 'Les Néerlandais prennent Malacca aux Portugais avec l aide du sultanat de Johor.', NULL, 12),
('Développement de l influence britannique en Malaisie', 'developpement-influence-britannique-malaisie-MY', '1786-01-01', '1874-01-01', 'Les Britanniques étendent progressivement leur influence commerciale et politique dans la péninsule malaise.', NULL, 22),
('Création des États malais fédérés', 'creation-etats-malais-federes-malaisie-MY', '1895-07-01', '1895-07-01', 'Perak, Selangor, Negeri Sembilan et Pahang sont regroupés sous une administration fédérale britannique.', NULL, 17),
('Invasion japonaise de la Malaisie', 'invasion-japonaise-malaisie-MY', '1941-12-08', '1942-02-15', 'Les forces japonaises envahissent la Malaisie et prennent le contrôle de la péninsule et de Singapour.', NULL, 13),
('Indépendance de la Fédération de Malaya', 'independance-federation-malaya-malaisie-MY', '1957-08-31', '1957-08-31', 'La Fédération de Malaya devient indépendante du Royaume-Uni.', NULL, 11),
('Formation de la Malaisie', 'formation-malaisie-MY', '1963-09-16', '1963-09-16', 'La Malaisie est créée par la fédération de Malaya avec Sabah, Sarawak et Singapour.', NULL, 17);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des premières communautés des Maldives', 'developpement-premieres-communautes-maldives-MV', '0100-01-01', '0500-01-01', 'Les premières communautés sédentaires se développent sur les atolls des Maldives grâce à la pêche et à l agriculture.', NULL, 16),
('Développement du commerce maritime des Maldives', 'developpement-commerce-maritime-maldives-MV', '0300-01-01', '0800-01-01', 'Les îles deviennent une étape des routes maritimes reliant l Inde, le Sri Lanka et l Asie du Sud-Est.', NULL, 25),
('Diffusion du bouddhisme aux Maldives', 'diffusion-bouddhisme-maldives-MV', '0300-01-01', '1100-01-01', 'Le bouddhisme devient progressivement la principale tradition religieuse de l archipel.', NULL, 23),
('Développement des échanges avec le Sri Lanka', 'developpement-echanges-sri-lanka-maldives-MV', '0500-01-01', '1200-01-01', 'Les Maldives renforcent leurs échanges commerciaux et culturels avec le Sri Lanka.', NULL, 25),
('Développement de la pêche aux Maldives', 'developpement-peche-maldives-MV', '0600-01-01', '1200-01-01', 'La pêche et l exploitation des ressources marines deviennent des activités essentielles de l économie insulaire.', NULL, 25),
('Développement des royaumes insulaires', 'developpement-royaumes-insulaires-maldives-MV', '0800-01-01', '1100-01-01', 'Les différentes îles et atolls s organisent progressivement autour de pouvoirs locaux.', NULL, 16),
('Diffusion de l islam aux Maldives', 'diffusion-islam-maldives-MV', '1153-01-01', '1153-01-01', 'L islam devient la religion officielle des Maldives sous le règne du sultan Muhammad al-Adil.', NULL, 23),
('Fondation du sultanat des Maldives', 'fondation-sultanat-maldives-MV', '1153-01-01', '1153-01-01', 'Le pouvoir politique de l archipel est réorganisé autour d un sultanat musulman.', NULL, 16),
('Développement du commerce de la noix de coco', 'developpement-commerce-noix-coco-maldives-MV', '1200-01-01', '1500-01-01', 'Les produits issus du cocotier, notamment les fibres de coco, participent au commerce maritime régional.', NULL, 25),
('Développement des relations commerciales avec les marchands arabes', 'developpement-relations-marchands-arabes-maldives-MV', '1200-01-01', '1500-01-01', 'Les Maldives intensifient leurs échanges avec les marchands arabes et les réseaux commerciaux de l océan Indien.', NULL, 25),
('Développement de Malé comme centre politique', 'developpement-male-centre-politique-maldives-MV', '1300-01-01', '1600-01-01', 'Malé s affirme progressivement comme le principal centre politique et commercial de l archipel.', NULL, 22),
('Voyage d Ibn Battûta aux Maldives', 'voyage-ibn-battuta-maldives-MV', '1343-01-01', '1344-01-01', 'Ibn Battûta séjourne aux Maldives et décrit la société, le gouvernement et les pratiques religieuses de l archipel.', NULL, 24),
('Développement du sultanat de Malé', 'developpement-sultanat-male-maldives-MV', '1400-01-01', '1600-01-01', 'Le sultanat consolide son administration et son contrôle sur les différents atolls.', NULL, 5),
('Arrivée des Portugais dans l océan Indien', 'arrivee-portugais-ocean-indien-maldives-MV', '1500-01-01', '1550-01-01', 'L expansion portugaise dans l océan Indien modifie les routes commerciales autour des Maldives.', NULL, 13),
('Occupation portugaise de Malé', 'occupation-portugaise-male-maldives-MV', '1558-01-01', '1573-01-01', 'Les Portugais occupent Malé et tentent d imposer leur domination sur l archipel.', NULL, 13),
('Révolte contre l occupation portugaise', 'revolte-occupation-portugaise-maldives-MV', '1573-01-01', '1573-01-01', 'La résistance menée par Muhammad Thakurufaanu met fin à la domination portugaise aux Maldives.', NULL, 9),
('Développement des relations avec les puissances européennes', 'developpement-relations-puissances-europeennes-maldives-MV', '1600-01-01', '1800-01-01', 'Les Maldives entretiennent des relations commerciales avec différentes puissances maritimes européennes et asiatiques.', NULL, 25),
('Protectorat britannique sur les Maldives', 'protectorat-britannique-maldives-MV', '1887-12-16', '1887-12-16', 'Les Maldives deviennent un protectorat britannique tout en conservant leur sultanat.', NULL, 14),
('Indépendance des Maldives', 'independance-maldives-MV', '1965-07-26', '1965-07-26', 'Les Maldives deviennent indépendantes du Royaume-Uni.', NULL, 11),
('Proclamation de la République des Maldives', 'proclamation-republique-maldives-MV', '1968-11-11', '1968-11-11', 'Le sultanat est aboli et la République des Maldives est proclamée.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des confédérations nomades des steppes', 'developpement-confederations-nomades-steppes-mongolie-MN', '0001-01-01', '0300-01-01', 'Les peuples nomades des steppes de Mongolie développent des structures politiques et militaires fondées sur l élevage et la mobilité.', NULL, 22),
('Développement de la confédération Xianbei', 'developpement-confederation-xianbei-mongolie-MN', '0093-01-01', '0234-01-01', 'La confédération Xianbei devient une puissance majeure des steppes de Mongolie et de Mandchourie.', NULL, 22),
('Développement du khaganat Rouran', 'developpement-khaganat-rouran-mongolie-MN', '0330-01-01', '0555-01-01', 'Les Rouran établissent un puissant empire nomade couvrant une grande partie des steppes mongoles.', NULL, 16),
('Développement du khaganat turc', 'developpement-khaganat-turc-mongolie-MN', '552-01-01', '603-01-01', 'Le premier Khaganat turc domine une grande partie des steppes et contrôle des routes commerciales de l Asie centrale.', NULL, 5),
('Développement du khaganat turc oriental', 'developpement-khaganat-turc-oriental-mongolie-MN', '603-01-01', '630-01-01', 'Le khaganat turc oriental devient le principal pouvoir des steppes de Mongolie.', NULL, 5),
('Fondation du khaganat ouïghour', 'fondation-khaganat-ouighour-mongolie-MN', '744-01-01', '744-01-01', 'Les Ouïghours fondent un khaganat centré sur les steppes de Mongolie après la défaite des Göktürks.', NULL, 16),
('Fondation d Ordu-Baliq', 'fondation-ordu-baliq-mongolie-MN', '744-01-01', '744-01-01', 'Ordu-Baliq devient la capitale du khaganat ouïghour et un important centre politique et commercial.', NULL, 16),
('Déclin du khaganat ouïghour', 'declin-khaganat-ouighour-mongolie-MN', '840-01-01', '840-01-01', 'Les Kirghizes défont le khaganat ouïghour et provoquent la dispersion de son pouvoir en Mongolie.', NULL, 9),
('Développement des tribus mongoles', 'developpement-tribus-mongoles-mongolie-MN', '0900-01-01', '1150-01-01', 'Les différentes tribus mongoles se structurent et rivalisent pour le contrôle des steppes et des routes commerciales.', NULL, 22),
('Naissance de Temüjin', 'naissance-temujin-mongolie-MN', '1162-01-01', '1162-01-01', 'Temüjin, futur Gengis Khan, naît dans les steppes mongoles et deviendra le fondateur de l Empire mongol.', NULL, 1),
('Unification des tribus mongoles', 'unification-tribus-mongoles-mongolie-MN', '1189-01-01', '1206-01-01', 'Temüjin rassemble progressivement les principales tribus mongoles sous son autorité.', NULL, 22),
('Proclamation de Gengis Khan', 'proclamation-gengis-khan-mongolie-MN', '1206-01-01', '1206-01-01', 'Temüjin est proclamé Gengis Khan lors d une grande assemblée des chefs mongols.', NULL, 4),
('Conquête de la dynastie Jin', 'conquete-dynastie-jin-mongolie-MN', '1211-01-01', '1234-01-01', 'Les Mongols conquièrent progressivement les territoires contrôlés par la dynastie Jin dans le nord de la Chine.', NULL, 12),
('Conquête de l Asie centrale', 'conquete-asie-centrale-mongolie-MN', '1219-01-01', '1221-01-01', 'Les armées de Gengis Khan conquièrent une grande partie de l empire du Khwarezm en Asie centrale.', NULL, 12),
('Invasion de la Rus de Kiev', 'invasion-rus-kiev-mongolie-MN', '1237-01-01', '1240-01-01', 'Les armées mongoles envahissent les principautés de la Rus de Kiev et étendent l Empire mongol vers l ouest.', NULL, 13),
('Fondation de la dynastie Yuan', 'fondation-dynastie-yuan-mongolie-MN', '1271-01-01', '1271-01-01', 'Kubilai Khan proclame la dynastie Yuan en Chine et établit son pouvoir impérial depuis Khanbalik.', NULL, 16),
('Conquête de la Chine des Song', 'conquete-chine-song-mongolie-MN', '1268-01-01', '1279-01-01', 'Les Mongols achèvent la conquête de la Chine des Song et unifient la Chine sous la dynastie Yuan.', NULL, 12),
('Déclin de la dynastie Yuan', 'declin-dynastie-yuan-mongolie-MN', '1368-01-01', '1368-01-01', 'La dynastie Yuan est renversée en Chine et les Mongols se replient vers la Mongolie.', NULL, 9),
('Fondation du khanat mongol du Nord', 'fondation-khanat-mongol-nord-mongolie-MN', '1368-01-01', '1400-01-01', 'Les dirigeants mongols établissent de nouveaux centres de pouvoir dans les steppes après la chute des Yuan.', NULL, 16),
('Proclamation de l indépendance de la Mongolie', 'independance-mongolie-MN', '1911-12-29', '1911-12-29', 'La Mongolie proclame son indépendance de la domination Qing et établit le Bogd Khanat.', NULL, 11);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des cités Pyu', 'developpement-cites-pyu-myanmar-MM', '0100-01-01', '0800-01-01', 'Les cités Pyu se développent dans la vallée de l Irrawaddy et participent aux réseaux commerciaux de l Asie du Sud-Est.', NULL, 16),
('Diffusion du bouddhisme au Myanmar', 'diffusion-bouddhisme-myanmar-MM', '0200-01-01', '0800-01-01', 'Le bouddhisme se diffuse progressivement parmi les populations des cités Pyu et dans la vallée de l Irrawaddy.', NULL, 23),
('Développement de Sri Ksetra', 'developpement-sri-ksetra-myanmar-MM', '0300-01-01', '0800-01-01', 'Sri Ksetra devient l un des principaux centres politiques et culturels des Pyu.', NULL, 16),
('Développement du royaume de Thaton', 'developpement-royaume-thaton-myanmar-MM', '0500-01-01', '1000-01-01', 'Thaton devient un important centre môn du sud du Myanmar et participe aux échanges maritimes régionaux.', NULL, 16),
('Développement du royaume de Pagan', 'developpement-royaume-pagan-myanmar-MM', '0849-01-01', '1000-01-01', 'Pagan se développe comme centre politique majeur de la vallée de l Irrawaddy.', NULL, 16),
('Fondation du royaume de Pagan', 'fondation-royaume-pagan-myanmar-MM', '0849-01-01', '0849-01-01', 'La ville de Pagan devient le centre d un royaume qui va progressivement unifier une grande partie du Myanmar.', NULL, 16),
('Règne d Anawrahta', 'regne-anawrahta-myanmar-MM', '1044-01-01', '1077-01-01', 'Le règne d Anawrahta marque l expansion de Pagan et le renforcement du bouddhisme theravada.', NULL, 5),
('Conquête de Thaton par Pagan', 'conquete-thaton-pagan-myanmar-MM', '1057-01-01', '1057-01-01', 'Pagan conquiert Thaton et étend son influence sur le sud du Myanmar.', NULL, 12),
('Développement de Bagan', 'developpement-bagan-myanmar-MM', '1100-01-01', '1200-01-01', 'Bagan connaît une période de prospérité et devient un grand centre religieux et culturel.', NULL, 24),
('Construction des temples de Bagan', 'construction-temples-bagan-myanmar-MM', '1050-01-01', '1250-01-01', 'Des milliers de temples et de monastères sont construits dans la plaine de Bagan.', NULL, 17),
('Invasion mongole de Pagan', 'invasion-mongole-pagan-myanmar-MM', '1277-01-01', '1287-01-01', 'Les Mongols interviennent dans le royaume de Pagan et contribuent à son effondrement politique.', NULL, 13),
('Fondation du royaume d Ava', 'fondation-royaume-ava-myanmar-MM', '1364-01-01', '1364-01-01', 'Le royaume d Ava est fondé en Haute-Birmanie après la fragmentation politique qui suit la chute de Pagan.', NULL, 16),
('Fondation du royaume d Hanthawaddy', 'fondation-royaume-hanthawaddy-myanmar-MM', '1287-01-01', '1287-01-01', 'Le royaume môn d Hanthawaddy s affirme dans le sud du Myanmar après la disparition de Pagan.', NULL, 16),
('Développement du royaume de Taungû', 'developpement-royaume-taungu-myanmar-MM', '1486-01-01', '1550-01-01', 'Taungû devient progressivement une puissance majeure de la Birmanie centrale.', NULL, 16),
('Conquête de la Haute-Birmanie par Taungû', 'conquete-haute-birmanie-taungu-myanmar-MM', '1550-01-01', '1555-01-01', 'Le roi Bayinnaung étend le royaume de Taungû sur une grande partie de la Birmanie.', NULL, 12),
('Fondation de la dynastie Konbaung', 'fondation-dynastie-konbaung-myanmar-MM', '1752-01-01', '1752-01-01', 'Alaungpaya fonde la dynastie Konbaung après la chute du royaume de Hanthawaddy.', NULL, 16),
('Première guerre anglo-birmane', 'premiere-guerre-anglo-birmane-myanmar-MM', '1824-03-05', '1826-02-24', 'La guerre entre la Birmanie et la Compagnie britannique des Indes orientales se termine par le traité de Yandabo.', NULL, 6),
('Annexion de la Birmanie par les Britanniques', 'annexion-birmanie-britanniques-myanmar-MM', '1885-11-29', '1886-01-01', 'La chute du royaume Konbaung entraîne l intégration de la Birmanie à l Empire britannique des Indes.', NULL, 12),
('Indépendance de la Birmanie', 'independance-birmanie-myanmar-MM', '1948-01-04', '1948-01-04', 'La Birmanie devient indépendante du Royaume-Uni.', NULL, 11),
('Coup d État de Ne Win', 'coup-etat-ne-win-myanmar-MM', '1962-03-02', '1962-03-02', 'Ne Win renverse le gouvernement et établit un régime militaire en Birmanie.', NULL, 10);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des royaumes Kirata au Népal', 'developpement-royaumes-kirata-nepal-NP', '0001-01-01', '0300-01-01', 'Développement des royaumes Kirata dans la vallée de Katmandou et les régions environnantes.', NULL, 5),
('Diffusion du bouddhisme au Népal', 'diffusion-bouddhisme-nepal-NP', '0250-01-01', '0500-01-01', 'Diffusion progressive du bouddhisme dans la vallée de Katmandou et les territoires himalayens.', NULL, 23),
('Développement de la vallée de Katmandou', 'developpement-vallee-katmandou-nepal-NP', '0300-01-01', '0500-01-01', 'Développement urbain, agricole et commercial de la vallée de Katmandou.', NULL, 17),
('Fondation de la dynastie Licchavi', 'fondation-dynastie-licchavi-nepal-NP', '0400-01-01', '0500-01-01', 'Établissement de la dynastie Licchavi comme puissance dominante dans la vallée de Katmandou.', NULL, 16),
('Règne de Manadeva Ier', 'regne-manadeva-ier-nepal-NP', '0464-01-01', '0505-01-01', 'Règne de Manadeva Ier, l’un des souverains les plus importants de la période Licchavi.', NULL, 5),
('Développement de l’art Licchavi', 'developpement-art-licchavi-nepal-NP', '0500-01-01', '0700-01-01', 'Épanouissement de la sculpture, de l’architecture et de l’art religieux sous les Licchavi.', NULL, 24),
('Construction du temple de Changu Narayan', 'construction-temple-changu-narayan-nepal-NP', '0600-01-01', '0700-01-01', 'Développement et embellissement du complexe religieux de Changu Narayan.', NULL, 23),
('Développement du commerce transhimalayen', 'developpement-commerce-transhimalayen-nepal-NP', '0600-01-01', '0900-01-01', 'Expansion des échanges commerciaux reliant le Népal à l’Inde et au Tibet.', NULL, 25),
('Fondation de la dynastie Thakuri', 'fondation-dynastie-thakuri-nepal-NP', '0879-01-01', '1000-01-01', 'Établissement des souverains Thakuri après le déclin de la période Licchavi.', NULL, 16),
('Développement du royaume de Bhaktapur', 'developpement-royaume-bhaktapur-nepal-NP', '1000-01-01', '1200-01-01', 'Renforcement de Bhaktapur comme centre politique et commercial de la vallée.', NULL, 17),
('Fondation de la dynastie Malla', 'fondation-dynastie-malla-nepal-NP', '1200-01-01', '1250-01-01', 'Émergence de la dynastie Malla comme nouvelle puissance politique dans la vallée de Katmandou.', NULL, 16),
('Règne de Jayasthiti Malla', 'regne-jayasthiti-malla-nepal-NP', '1382-01-01', '1395-01-01', 'Règne de Jayasthiti Malla, associé à d’importantes réformes sociales et administratives.', NULL, 5),
('Développement de l’architecture Malla', 'developpement-architecture-malla-nepal-NP', '1400-01-01', '1700-01-01', 'Épanouissement des palais, temples, places et pagodes de la vallée de Katmandou.', NULL, 24),
('Division du royaume de Katmandou', 'division-royaume-katmandou-nepal-NP', '1484-01-01', '1484-01-01', 'Division du royaume de la vallée entre plusieurs États dirigés par des branches de la dynastie Malla.', NULL, 22),
('Fondation du royaume de Gorkha', 'fondation-royaume-gorkha-nepal-NP', '1559-01-01', '1559-01-01', 'Fondation du royaume de Gorkha par Dravya Shah.', NULL, 16),
('Unification du Népal par Prithvi Narayan Shah', 'unification-nepal-prithvi-narayan-shah-nepal-NP', '1743-01-01', '1775-01-01', 'Conquête et unification progressive de nombreux royaumes de l’Himalaya central sous Gorkha.', NULL, 12),
('Conquête de Katmandou par Gorkha', 'conquete-katmandou-gorkha-nepal-NP', '1768-09-25', '1768-09-25', 'Prise de Katmandou par les forces de Prithvi Narayan Shah et intégration de la ville au royaume unifié.', NULL, 12),
('Guerre anglo-népalaise', 'guerre-anglo-nepalaise-nepal-NP', '1814-11-01', '1816-03-04', 'Conflit entre le royaume du Népal et la Compagnie britannique des Indes orientales.', NULL, 6),
('Traité de Sugauli', 'traite-sugauli-nepal-NP', '1816-03-04', '1816-03-04', 'Traité mettant fin à la guerre anglo-népalaise et fixant les frontières du Népal avec les territoires britanniques.', NULL, 14),
('Établissement de la démocratie multipartite au Népal', 'etablissement-democratie-multipartite-nepal-NP', '1990-04-19', '1990-11-09', 'Mouvement politique conduisant au rétablissement d’un système démocratique multipartite et à une nouvelle constitution.', NULL, 22);
INSERT INTO events (title, slug, date_start, date_end, description, image_url, type_id) VALUES
('Développement des établissements de Magan', 'developpement-etablissements-magan-oman-OM', '0001-01-01', '0300-01-01', 'Développement des communautés et centres commerciaux de l’ancien Magan dans la péninsule d’Oman.', NULL, 17),
